export function getAvailableGrades(board: string): string[] {
  return Object.keys(TEXTBOOK_TAXONOMY[board] || {});
}

export function getAvailableSubjects(board: string, grade: string, stream?: string): string[] {
  const subjects = TEXTBOOK_TAXONOMY[board]?.[grade] || [];
  return subjects
    .filter((item) => !stream || !item.stream || item.stream === stream)
    .map((item) => item.subject);
}

export function getSyllabusChapters(board: string, grade: string, subject: string, stream?: string): ChapterInfo[] {
  const subjects = TEXTBOOK_TAXONOMY[board]?.[grade] || [];
  const subjectData = subjects.find(
    (item) => item.subject === subject && (!stream || !item.stream || item.stream === stream)
  );

  return subjectData?.chapters || [];
}
